def normalise_policies(apps, schema_editor):
    """
    Policies now apply automatically whenever they are active, so make the data
    reflect what actually applied before: lowercase priority/status, rename
    "critical" to "urgent", and keep a single active simple-mode policy per priority.
    """
    SLAPolicy = apps.get_model('sla', 'SLAPolicy')

    for policy in SLAPolicy.objects.all():
        priority = (policy.priority or '').lower()
        priority = 'urgent' if priority == 'critical' else priority
        status = (policy.status or '').lower()
        if priority != policy.priority or status != policy.status:
            SLAPolicy.objects.filter(pk=policy.pk).update(priority=priority, status=status)
    SLAPolicy.objects.filter(name='Critical Priority SLA').update(name='Urgent Priority SLA')

    by_priority = {}
    for policy in SLAPolicy.objects.filter(status='active', use_custom_rules=False):
        by_priority.setdefault(policy.priority, []).append(policy)

    for policies in by_priority.values():
        if len(policies) < 2:
            continue
        # Prefer the policy that was applying to new tickets, then the most recently edited
        keeper = max(policies, key=lambda p: (p.apply_to_new_tickets, p.updated_at))
        for policy in policies:
            if policy.pk != keeper.pk:
                SLAPolicy.objects.filter(pk=policy.pk).update(status='inactive')
                print(f'\n  SLA policy "{policy.name}" (id {policy.pk}) set to inactive: '
                      f'"{keeper.name}" already covers {keeper.priority} priority.')


